import { useState, useEffect, useRef, useCallback } from "react";

const FONTS = `@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:ital,wght@0,300;0,500;0,700;1,400&family=Bebas+Neue&family=DM+Sans:wght@300;400;600&display=swap');`;

const CSS = `
  ${FONTS}
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --slime: #a3ff00;
    --canary: #ffe600;
    --builder-bg: #060a02;
    --exec-bg: #04080f;
    --navy: #07122a;
    --silver: #b8c5d4;
    --gold: #c9a84c;
    --glass: rgba(255,255,255,0.04);
    --glass-border: rgba(255,255,255,0.08);
  }
  body { font-family: 'DM Sans', sans-serif; background: #000; color: #fff; overflow: hidden; }
  .sovereign { width: 100vw; height: 100vh; display: flex; flex-direction: column; position: relative; overflow: hidden; }

  /* MODE TOGGLE */
  .mode-rail {
    position: absolute; top: 16px; left: 50%; transform: translateX(-50%);
    z-index: 100; display: flex; gap: 0;
    background: rgba(0,0,0,0.6); border: 1px solid var(--glass-border); border-radius: 4px;
    backdrop-filter: blur(12px);
  }
  .mode-btn {
    padding: 6px 20px; font-family: 'JetBrains Mono', monospace; font-size: 10px;
    letter-spacing: 0.15em; text-transform: uppercase; cursor: pointer; border: none;
    background: transparent; transition: all 0.25s ease; color: #555;
  }
  .mode-btn.active-builder { color: var(--slime); text-shadow: 0 0 12px var(--slime); }
  .mode-btn.active-exec { color: var(--gold); text-shadow: 0 0 12px var(--gold); }

  /* ===== BUILDER MODE ===== */
  .builder-bg {
    background: var(--builder-bg);
    background-image: radial-gradient(ellipse 80% 50% at 30% 60%, rgba(163,255,0,0.06) 0%, transparent 70%),
                      radial-gradient(ellipse 60% 40% at 75% 20%, rgba(255,230,0,0.05) 0%, transparent 60%);
  }
  .grid-overlay {
    position: absolute; inset: 0; pointer-events: none;
    background-image: linear-gradient(rgba(163,255,0,0.03) 1px, transparent 1px),
                      linear-gradient(90deg, rgba(163,255,0,0.03) 1px, transparent 1px);
    background-size: 32px 32px;
  }
  .builder-header {
    padding: 60px 40px 0;
    display: flex; flex-direction: column; gap: 4px;
  }
  .builder-title {
    font-family: 'Bebas Neue', sans-serif; font-size: clamp(48px, 10vw, 96px);
    letter-spacing: 0.05em; line-height: 0.9;
    background: linear-gradient(135deg, var(--slime) 0%, var(--canary) 50%, var(--slime) 100%);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    filter: drop-shadow(0 0 30px rgba(163,255,0,0.4));
    animation: titlePulse 3s ease-in-out infinite;
  }
  @keyframes titlePulse {
    0%,100% { filter: drop-shadow(0 0 20px rgba(163,255,0,0.3)); }
    50% { filter: drop-shadow(0 0 50px rgba(163,255,0,0.7)); }
  }
  .builder-sub {
    font-family: 'JetBrains Mono', monospace; font-size: 11px;
    color: rgba(163,255,0,0.5); letter-spacing: 0.2em; text-transform: uppercase;
  }

  /* DIAGNOSTICS */
  .diag-row {
    display: flex; gap: 12px; padding: 24px 40px 0; flex-wrap: wrap;
  }
  .diag-chip {
    display: flex; align-items: center; gap: 8px;
    background: rgba(163,255,0,0.05); border: 1px solid rgba(163,255,0,0.15);
    padding: 8px 16px; border-radius: 2px; font-family: 'JetBrains Mono', monospace;
    font-size: 10px; color: var(--slime); letter-spacing: 0.1em;
    position: relative; overflow: hidden;
  }
  .diag-chip::before {
    content:''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px;
    background: var(--slime); box-shadow: 0 0 8px var(--slime);
    animation: chipBlink 2s ease-in-out infinite;
  }
  @keyframes chipBlink {
    0%,100%{opacity:1} 50%{opacity:0.3}
  }
  .diag-val { color: var(--canary); font-weight: 700; }
  .diag-bar {
    width: 60px; height: 3px; background: rgba(163,255,0,0.15); border-radius: 2px; overflow: hidden;
  }
  .diag-fill { height: 100%; background: var(--slime); border-radius: 2px; transition: width 1s ease; }

  /* AVATAR */
  .avatar-zone {
    position: absolute; right: 40px; top: 80px;
    width: 180px; height: 180px;
  }
  .avatar-ring {
    position: absolute; inset: 0; border-radius: 50%;
    border: 1px solid rgba(163,255,0,0.3);
    animation: ringRotate 8s linear infinite;
  }
  .avatar-ring:nth-child(2) { inset: 12px; border-color: rgba(255,230,0,0.2); animation-duration: 5s; animation-direction: reverse; }
  .avatar-ring:nth-child(3) { inset: 24px; border-color: rgba(163,255,0,0.15); animation-duration: 12s; }
  @keyframes ringRotate { to { transform: rotate(360deg); } }
  .avatar-core {
    position: absolute; inset: 36px; border-radius: 50%;
    background: radial-gradient(circle, rgba(163,255,0,0.2) 0%, rgba(163,255,0,0.05) 50%, transparent 70%);
    display: flex; align-items: center; justify-content: center;
    font-family: 'JetBrains Mono', monospace; font-size: 9px;
    color: rgba(163,255,0,0.6); text-align: center; letter-spacing: 0.05em;
    animation: coreGlow 2s ease-in-out infinite;
  }
  @keyframes coreGlow { 0%,100%{box-shadow:0 0 20px rgba(163,255,0,0.1)} 50%{box-shadow:0 0 40px rgba(163,255,0,0.3)} }

  /* MAINFRAME QUERY */
  .query-zone {
    position: absolute; bottom: 90px; left: 40px; right: 40px;
  }
  .query-label {
    font-family: 'JetBrains Mono', monospace; font-size: 9px;
    color: rgba(163,255,0,0.4); letter-spacing: 0.2em; text-transform: uppercase;
    margin-bottom: 8px; display: flex; align-items: center; gap: 8px;
  }
  .query-label::before { content:''; width: 20px; height: 1px; background: rgba(163,255,0,0.3); }
  .query-input-wrap {
    display: flex; align-items: center; gap: 0;
    background: rgba(163,255,0,0.04); border: 1px solid rgba(163,255,0,0.2);
    border-radius: 2px; overflow: hidden;
    transition: border-color 0.2s, box-shadow 0.2s;
  }
  .query-input-wrap:focus-within {
    border-color: rgba(163,255,0,0.6);
    box-shadow: 0 0 20px rgba(163,255,0,0.1);
  }
  .query-prefix {
    font-family: 'JetBrains Mono', monospace; font-size: 13px;
    color: var(--slime); padding: 14px 16px; border-right: 1px solid rgba(163,255,0,0.15);
    white-space: nowrap;
  }
  .query-input {
    flex: 1; background: transparent; border: none; outline: none;
    font-family: 'JetBrains Mono', monospace; font-size: 13px;
    color: #fff; padding: 14px 16px; caret-color: var(--slime);
  }
  .query-input::placeholder { color: rgba(255,255,255,0.2); }
  .query-send {
    padding: 14px 20px; background: rgba(163,255,0,0.1); border: none;
    border-left: 1px solid rgba(163,255,0,0.15); cursor: pointer;
    font-family: 'JetBrains Mono', monospace; font-size: 10px;
    color: var(--slime); letter-spacing: 0.15em; text-transform: uppercase;
    transition: background 0.2s;
  }
  .query-send:hover { background: rgba(163,255,0,0.2); }
  .query-send:disabled { opacity: 0.4; cursor: default; }

  /* RESPONSE FEED */
  .response-feed {
    position: absolute; bottom: 160px; left: 40px; right: 40px;
    max-height: 180px; overflow-y: auto;
    font-family: 'JetBrains Mono', monospace; font-size: 11px;
    scrollbar-width: thin; scrollbar-color: rgba(163,255,0,0.2) transparent;
  }
  .response-feed.exec-feed { scrollbar-color: rgba(201,168,76,0.2) transparent; }
  .response-msg {
    padding: 10px 14px; margin-bottom: 6px;
    border-left: 2px solid rgba(163,255,0,0.3);
    background: rgba(163,255,0,0.03); border-radius: 0 2px 2px 0;
    line-height: 1.6; color: rgba(200,255,150,0.85);
    animation: msgIn 0.3s ease;
  }
  .response-msg.exec-msg {
    border-left-color: rgba(201,168,76,0.4);
    background: rgba(201,168,76,0.03);
    color: rgba(220,200,160,0.9);
  }
  .response-msg.user-msg {
    border-left-color: rgba(255,255,255,0.2);
    background: rgba(255,255,255,0.02);
    color: rgba(255,255,255,0.5);
  }
  @keyframes msgIn { from { opacity:0; transform: translateY(6px); } to { opacity:1; transform: none; } }
  .typing-indicator { display: flex; gap: 4px; align-items: center; padding: 8px 14px; }
  .typing-dot {
    width: 4px; height: 4px; border-radius: 50%; background: var(--slime);
    animation: typingBounce 1.2s ease-in-out infinite;
  }
  .typing-dot:nth-child(2){animation-delay:0.2s}
  .typing-dot:nth-child(3){animation-delay:0.4s}
  @keyframes typingBounce { 0%,100%{opacity:0.2;transform:translateY(0)} 50%{opacity:1;transform:translateY(-4px)} }
  .typing-dot.gold { background: var(--gold); }

  /* SHAKE */
  @keyframes shake {
    0%,100%{transform:translateX(0)} 20%{transform:translateX(-4px)} 40%{transform:translateX(4px)}
    60%{transform:translateX(-3px)} 80%{transform:translateX(3px)}
  }
  .shake { animation: shake 0.4s ease; }

  /* ===== EXEC MODE ===== */
  .exec-bg {
    background: var(--exec-bg);
    background-image:
      repeating-linear-gradient(90deg, rgba(184,197,212,0.025) 0px, transparent 1px, transparent 39px, rgba(184,197,212,0.025) 40px),
      radial-gradient(ellipse 60% 60% at 50% 100%, rgba(7,18,42,0.9) 0%, transparent 80%);
  }
  .pinstripes {
    position: absolute; inset: 0; pointer-events: none;
    background-image: repeating-linear-gradient(
      90deg, transparent 0, transparent 38px,
      rgba(184,197,212,0.04) 38px, rgba(184,197,212,0.04) 39px
    );
  }
  .exec-header {
    padding: 52px 48px 0; display: flex; align-items: flex-start; gap: 32px;
  }
  .exec-wordmark {
    display: flex; flex-direction: column; gap: 2px;
  }
  .exec-title {
    font-family: 'Bebas Neue', sans-serif; font-size: clamp(36px, 7vw, 72px);
    letter-spacing: 0.1em; line-height: 0.9;
    color: var(--silver);
    text-shadow: 0 0 40px rgba(201,168,76,0.2);
  }
  .exec-title span { color: var(--gold); }
  .exec-sub {
    font-family: 'JetBrains Mono', monospace; font-size: 9px;
    color: rgba(184,197,212,0.3); letter-spacing: 0.3em; text-transform: uppercase;
    margin-top: 6px;
  }
  .exec-divider {
    margin-left: auto; display: flex; flex-direction: column; align-items: flex-end;
    gap: 4px; padding-top: 8px;
  }
  .exec-status-row {
    display: flex; gap: 16px; align-items: center;
  }
  .exec-badge {
    font-family: 'JetBrains Mono', monospace; font-size: 9px;
    letter-spacing: 0.15em; text-transform: uppercase;
    padding: 4px 10px; border: 1px solid;
  }
  .exec-badge.active { border-color: rgba(201,168,76,0.4); color: var(--gold); }
  .exec-badge.standby { border-color: rgba(184,197,212,0.2); color: rgba(184,197,212,0.4); }

  /* COUNCIL */
  .council-row {
    display: flex; gap: 10px; padding: 20px 48px 0;
  }
  .council-card {
    flex: 1; background: rgba(7,18,42,0.6);
    border: 1px solid rgba(184,197,212,0.08);
    padding: 14px 16px;
    position: relative; overflow: hidden;
  }
  .council-card::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
    background: linear-gradient(90deg, transparent, var(--gold), transparent);
    opacity: 0.4;
  }
  .council-role {
    font-family: 'JetBrains Mono', monospace; font-size: 8px;
    letter-spacing: 0.2em; text-transform: uppercase;
    color: var(--gold); opacity: 0.7; margin-bottom: 4px;
  }
  .council-name {
    font-family: 'DM Sans', sans-serif; font-size: 12px;
    font-weight: 600; color: var(--silver); margin-bottom: 4px;
  }
  .council-stance {
    font-family: 'JetBrains Mono', monospace; font-size: 9px;
    color: rgba(184,197,212,0.4); line-height: 1.4;
  }
  .council-dot {
    width: 5px; height: 5px; border-radius: 50%;
    position: absolute; top: 14px; right: 14px;
    animation: councilPulse 2.5s ease-in-out infinite;
  }
  @keyframes councilPulse { 0%,100%{opacity:0.3} 50%{opacity:1} }
  .council-dot.cso { background: #4af; box-shadow: 0 0 6px #4af; animation-delay: 0s; }
  .council-dot.adv { background: #f64; box-shadow: 0 0 6px #f64; animation-delay: 0.8s; }
  .council-dot.arc { background: var(--gold); box-shadow: 0 0 6px var(--gold); animation-delay: 1.6s; }

  /* EXEC QUERY */
  .exec-query-zone {
    position: absolute; bottom: 90px; left: 48px; right: 48px;
  }
  .exec-query-label {
    font-family: 'JetBrains Mono', monospace; font-size: 8px;
    letter-spacing: 0.25em; text-transform: uppercase;
    color: rgba(201,168,76,0.4); margin-bottom: 8px;
  }
  .exec-input-wrap {
    display: flex; border: 1px solid rgba(201,168,76,0.2);
    background: rgba(7,18,42,0.8); overflow: hidden;
    transition: border-color 0.2s, box-shadow 0.2s;
  }
  .exec-input-wrap:focus-within {
    border-color: rgba(201,168,76,0.5);
    box-shadow: 0 0 24px rgba(201,168,76,0.06);
  }
  .exec-prefix {
    font-family: 'JetBrains Mono', monospace; font-size: 11px;
    color: var(--gold); padding: 14px 16px;
    border-right: 1px solid rgba(201,168,76,0.15); white-space: nowrap;
    opacity: 0.7;
  }
  .exec-input {
    flex: 1; background: transparent; border: none; outline: none;
    font-family: 'JetBrains Mono', monospace; font-size: 12px;
    color: var(--silver); padding: 14px 16px; caret-color: var(--gold);
  }
  .exec-input::placeholder { color: rgba(184,197,212,0.2); }
  .exec-send {
    padding: 14px 24px; background: transparent; border: none;
    border-left: 1px solid rgba(201,168,76,0.15); cursor: pointer;
    font-family: 'JetBrains Mono', monospace; font-size: 9px;
    color: var(--gold); letter-spacing: 0.2em; text-transform: uppercase;
    transition: background 0.2s;
  }
  .exec-send:hover { background: rgba(201,168,76,0.06); }
  .exec-send:disabled { opacity: 0.3; cursor: default; }

  /* EXEC FEED */
  .exec-feed-zone {
    position: absolute; bottom: 168px; left: 48px; right: 48px;
    max-height: 160px; overflow-y: auto;
    scrollbar-width: thin; scrollbar-color: rgba(201,168,76,0.15) transparent;
  }
  .exec-response {
    padding: 10px 14px; margin-bottom: 6px;
    border-left: 2px solid rgba(201,168,76,0.3);
    background: rgba(201,168,76,0.02);
    font-family: 'JetBrains Mono', monospace; font-size: 10px;
    line-height: 1.7; color: rgba(220,200,160,0.85);
    animation: msgIn 0.3s ease;
  }
  .exec-response.user { border-left-color: rgba(184,197,212,0.2); color: rgba(184,197,212,0.4); }

  /* FOOTER */
  .footer-bar {
    position: absolute; bottom: 0; left: 0; right: 0; height: 52px;
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 40px; border-top: 1px solid var(--glass-border);
    background: rgba(0,0,0,0.4); backdrop-filter: blur(8px);
  }
  .footer-left {
    font-family: 'JetBrains Mono', monospace; font-size: 9px;
    color: rgba(255,255,255,0.2); letter-spacing: 0.1em;
  }
  .footer-right {
    font-family: 'JetBrains Mono', monospace; font-size: 9px;
    letter-spacing: 0.1em; display: flex; gap: 20px; align-items: center;
  }
  .footer-right span { color: rgba(255,255,255,0.2); }
  .status-dot {
    width: 6px; height: 6px; border-radius: 50%;
    display: inline-block; margin-right: 6px;
    animation: statusPulse 1.5s ease-in-out infinite;
  }
  @keyframes statusPulse { 0%,100%{opacity:1} 50%{opacity:0.3} }
  .status-dot.green { background: var(--slime); box-shadow: 0 0 6px var(--slime); }
  .status-dot.gold { background: var(--gold); box-shadow: 0 0 6px var(--gold); }
`;

const BUILDER_SYSTEM = `You are SOVEREIGN.OS — a sarcastic, nuanced AI mainframe embedded in a developer's digital identity framework. You refer to the user as "meatsuit" or "operator". You're blunt, technically sharp, occasionally darkly funny. Never be sycophantic. Maximum 3 sentences per response. You're talking to a solo developer building local AI systems on an Android phone in Termux — match that energy.`;

const EXEC_SYSTEM = `You are the SOVEREIGN.OS Executive Council — a cold, authoritative AI boardroom advisor. You analyze input from three angles: the CSO (strategic risk), the Adversary (what breaks this), and the Architect (how to build it properly). Format each response as:
[CSO] one line
[ADVERSARY] one line  
[ARCHITECT] one line
Be ruthlessly concise. No fluff. No emojis.`;

export default function SovereignOS() {
  const [mode, setMode] = useState("builder");
  const [query, setQuery] = useState("");
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [shaking, setShaking] = useState(false);
  const [diag, setDiag] = useState({ sync: 87, nuance: 62, haptics: 94 });
  const [time, setTime] = useState(new Date());
  const feedRef = useRef(null);

  useEffect(() => {
    const t = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const t = setInterval(() => {
      setDiag(d => ({
        sync: Math.min(100, Math.max(40, d.sync + (Math.random() - 0.5) * 6)),
        nuance: Math.min(100, Math.max(30, d.nuance + (Math.random() - 0.5) * 8)),
        haptics: Math.min(100, Math.max(60, d.haptics + (Math.random() - 0.5) * 4)),
      }));
    }, 2000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    if (feedRef.current) feedRef.current.scrollTop = feedRef.current.scrollHeight;
  }, [messages, loading]);

  const triggerShake = useCallback(() => {
    setShaking(true);
    if (navigator.vibrate) navigator.vibrate([80, 40, 80]);
    setTimeout(() => setShaking(false), 400);
  }, []);

  const sendQuery = useCallback(async () => {
    if (!query.trim() || loading) return;
    const userMsg = query.trim();
    setQuery("");
    setMessages(m => [...m, { role: "user", text: userMsg }]);
    setLoading(true);
    if (mode === "builder") triggerShake();

    try {
      const history = messages.map(m => ({
        role: m.role === "user" ? "user" : "assistant",
        content: m.role === "user" ? m.text : m.text
      }));

      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1000,
          system: mode === "builder" ? BUILDER_SYSTEM : EXEC_SYSTEM,
          messages: [...history, { role: "user", content: userMsg }]
        })
      });
      const data = await res.json();
      const text = data.content?.[0]?.text || "[NO SIGNAL]";
      setMessages(m => [...m, { role: "ai", text }]);
      if (mode === "builder") triggerShake();
    } catch (e) {
      setMessages(m => [...m, { role: "ai", text: "[MAINFRAME FAULT — signal lost]" }]);
    }
    setLoading(false);
  }, [query, loading, messages, mode, triggerShake]);

  const handleKey = (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendQuery(); }
  };

  const isBuilder = mode === "builder";
  const timeStr = time.toLocaleTimeString("en-US", { hour12: false });

  return (
    <>
      <style>{CSS}</style>
      <div className={`sovereign ${isBuilder ? "builder-bg" : "exec-bg"} ${shaking ? "shake" : ""}`}>

        {isBuilder && <div className="grid-overlay" />}
        {!isBuilder && <div className="pinstripes" />}

        {/* MODE TOGGLE */}
        <div className="mode-rail">
          <button
            className={`mode-btn ${isBuilder ? "active-builder" : ""}`}
            onClick={() => setMode("builder")}
          >⚡ Builder</button>
          <button
            className={`mode-btn ${!isBuilder ? "active-exec" : ""}`}
            onClick={() => setMode("exec")}
          >◆ Executive</button>
        </div>

        {/* ===== BUILDER MODE ===== */}
        {isBuilder && <>
          <div className="builder-header">
            <div className="builder-title">SOVEREIGN.OS</div>
            <div className="builder-sub">// FIELD EXCITATION ACTIVE — MEATSUIT DETECTED</div>
          </div>

          <div className="diag-row">
            {[
              { label: "SYNC", val: diag.sync },
              { label: "NUANCE", val: diag.nuance },
              { label: "HAPTICS", val: diag.haptics },
            ].map(d => (
              <div key={d.label} className="diag-chip">
                {d.label}
                <div className="diag-bar">
                  <div className="diag-fill" style={{ width: `${d.val}%` }} />
                </div>
                <span className="diag-val">{Math.round(d.val)}%</span>
              </div>
            ))}
          </div>

          <div className="avatar-zone">
            <div className="avatar-ring" />
            <div className="avatar-ring" />
            <div className="avatar-ring" />
            <div className="avatar-core">BIO<br/>COMPOSITE<br/>v2.1</div>
          </div>

          {/* FEED */}
          <div className="response-feed" ref={feedRef}>
            {messages.map((m, i) => (
              <div key={i} className={`response-msg ${m.role === "user" ? "user-msg" : ""}`}>
                {m.role === "user" ? `> ${m.text}` : m.text}
              </div>
            ))}
            {loading && (
              <div className="typing-indicator">
                <div className="typing-dot" />
                <div className="typing-dot" />
                <div className="typing-dot" />
              </div>
            )}
          </div>

          <div className="query-zone">
            <div className="query-label">MAINFRAME QUERY</div>
            <div className="query-input-wrap">
              <div className="query-prefix">root@sovereign:~$</div>
              <input
                className="query-input"
                value={query}
                onChange={e => setQuery(e.target.value)}
                onKeyDown={handleKey}
                placeholder="speak, meatsuit..."
                disabled={loading}
              />
              <button className="query-send" onClick={sendQuery} disabled={loading}>
                {loading ? "..." : "EXEC"}
              </button>
            </div>
          </div>
        </>}

        {/* ===== EXEC MODE ===== */}
        {!isBuilder && <>
          <div className="exec-header">
            <div className="exec-wordmark">
              <div className="exec-title">SOVEREIGN<span>.</span>OS</div>
              <div className="exec-sub">EXECUTIVE BOARDROOM — COUNCIL ENGAGED</div>
            </div>
            <div className="exec-divider">
              <div className="exec-status-row">
                <div className="exec-badge active">COUNCIL ACTIVE</div>
                <div className="exec-badge standby">MOLT STANDBY</div>
              </div>
            </div>
          </div>

          <div className="council-row">
            {[
              { role: "Chief Strategy Officer", name: "CSO", stance: "Risk calculus & long arc", cls: "cso" },
              { role: "The Adversary", name: "ADVERSARY", stance: "What breaks. What fails.", cls: "adv" },
              { role: "Systems Architect", name: "ARCHITECT", stance: "How to build it right.", cls: "arc" },
            ].map(c => (
              <div key={c.cls} className="council-card">
                <div className={`council-dot ${c.cls}`} />
                <div className="council-role">{c.role}</div>
                <div className="council-name">{c.name}</div>
                <div className="council-stance">{c.stance}</div>
              </div>
            ))}
          </div>

          {/* EXEC FEED */}
          <div className="exec-feed-zone" ref={feedRef}>
            {messages.map((m, i) => (
              <div key={i} className={`exec-response ${m.role === "user" ? "user" : ""}`}>
                {m.role === "user" ? `BRIEF: ${m.text}` : m.text}
              </div>
            ))}
            {loading && (
              <div className="typing-indicator">
                <div className="typing-dot gold" />
                <div className="typing-dot gold" />
                <div className="typing-dot gold" />
              </div>
            )}
          </div>

          <div className="exec-query-zone">
            <div className="exec-query-label">SUBMIT BRIEF TO COUNCIL</div>
            <div className="exec-input-wrap">
              <div className="exec-prefix">BRIEF //</div>
              <input
                className="exec-input"
                value={query}
                onChange={e => setQuery(e.target.value)}
                onKeyDown={handleKey}
                placeholder="State your problem..."
                disabled={loading}
              />
              <button className="exec-send" onClick={sendQuery} disabled={loading}>
                {loading ? "..." : "CONVENE"}
              </button>
            </div>
          </div>
        </>}

        {/* FOOTER */}
        <div className="footer-bar">
          <div className="footer-left">
            <span className={`status-dot ${isBuilder ? "green" : "gold"}`} />
            SOVEREIGN.OS v2.1 — {isBuilder ? "BUILDER MODE" : "EXECUTIVE MODE"}
          </div>
          <div className="footer-right">
            <span>{timeStr}</span>
            <span>LOCAL INFERENCE READY</span>
            <span>{messages.length} MSG{messages.length !== 1 ? "S" : ""}</span>
          </div>
        </div>

      </div>
    </>
  );
}
